const arabicToEnglish = Object.fromEntries(
  Object.entries(englishToArabic).map(([english, arabic]) => [arabic, english]),
);

export function translateText(text: string, language: Language) {
  const prefix = text.match(/^\s*/)?.[0] ?? "";
  const suffix = text.match(/\s*$/)?.[0] ?? "";
  const value = text.trim().replace(/\s+/g, " ");
  if (!value) return text;

  const translated = language === "ar" ? englishToArabic[value] : arabicToEnglish[value];
  return translated ? `${prefix}${translated}${suffix}` : text;
}
